import{_ as i,o as a,c as n,a5 as h}from"./chunks/framework.a5no_H3L.js";const g=JSON.parse('{"title":"WebFlux 响应式编程","description":"Spring MVC 的线程模型是「一请求一线程」：200 个并发请求就需要 200 个线程。线程消耗内存（每个约 1MB 栈空间），切换消耗 CPU。当并发量到达万级，阻塞模型的瓶颈不在业务逻辑，而在线程等待——等数据库、等下游 HTTP、等磁盘 IO。WebFlux 换了一种思路：不给每个请求分配线程，而是用少量线程通过事件驱动处理所有请求。","frontmatter":{},"headers":[],"relativePath":"spring/03-web/chapter-06-webflux.md","filePath":"spring/03-web/chapter-06-webflux.md"}'),l={name:"spring/03-web/chapter-06-webflux.md"};function t(k,s,p,e,E,r){return a(),n("div",null,[...s[0]||(s[0]=[h("",52)])])}const y=i(l,[["render",t]]);export{g as __pageData,y as default};
